import java.util.List;

/**
 * Abstract class Creature - A class representing shared characteristics of creatures(animals and plants.)
 *
 * @version 2022/03/02
 */
public abstract class Creature
{
    @FunctionalInterface
    protected interface CreatureFactory
    {
        Creature create(Field field, Location location);
    }

    // Whether the creature is alive or not.
    private boolean alive;
    // The creature's field.
    private Field field;
    // The creature's position in the field.
    private Location location;


    /**
     * Create a new creature at location in field.
     * 
     * @param field The field currently occupied.
     * @param location The location within the field.
     */
    public Creature(Field field, Location location)
    {
        alive = true;
        this.field = field;
        setLocation(location);
    }

    /**
     * Make this creature act - that is: make it do
     * whatever it wants/needs to do.
     * @param newCreatures A list to receive newly born creatures.
     * @param atDayTime true if current step is daytime false otherwise.
     * @param oxygenLevel The inital level of dissolved oxygen in the water.
     * @param disease The disease may happened during simulation.  
     * @param step current step.
     * 
     * @return the oxygen level the species produced or consumed after action.
     */
    abstract public double act(List<Creature> newCreatures, boolean atDayTime, double oxygenLevel, Disease disease, int step);

    /**
     * Check whether the creature is alive or not.
     * @return true if the creature is still alive.
     */
    protected boolean isAlive()
    {
        return alive;
    }

      /**
     * Indicate that the creature is no longer alive.
     * It is removed from the field.
     */
    protected void setDead()
    {
        alive = false;
        if(location != null) {
            field.clear(location);
            location = null;
            field = null;
        }
    }

    /**
     * Return the creature's location.
     * @return The creature's location.
     */
    protected Location getLocation()
    {
        return location;
    }

    /**
     * Place the creature at the new location in the given field.
     * @param newLocation The creature's new location.
     */
    protected void setLocation(Location newLocation)
    {
        if(location != null) {
            field.clear(location);
        }
        location = newLocation;
        field.place(this, newLocation);
    }

     /**
     * Return the creature's field.
     * @return The creature's field.
     */
    protected Field getField()
    {
        return field;
    }

    /**
     * Create new creatures into free adjacent locations.
     */
    protected void createAdjacentCreatures(List<Creature> newCreatures, int count, CreatureFactory factory)
    {
        List<Location> freeLocations = field.getFreeAdjacentLocations(location);
        for(int created = 0; created < count && !freeLocations.isEmpty(); created++) {
            Location where = freeLocations.remove(0);
            newCreatures.add(factory.create(field, where));
        }
    }

}

import java.util.List;
import java.util.Random;

/**
  * A simple model of a seaweed.
 * 
 * Seaweed age, consume oxygen during the night and produce oxygen during the daytime, propogate, 
 * and may die of that or of weather.
 *
 * @version 2022/03/02
 */
public class Seaweed extends Creature
{

    // The age at which a seaweed becomes mature and could be edible.
    private static final int MATURE_AGE = 20;
    // The age to which a shrimp can live.
    private static final int MAX_AGE = 40;
    // The maximum number of births.
    private static final int MAX_PROPAGATE_SIZE = 1;
    // A shared random number generator to control breeding.
    private static final Random rand = Randomizer.getRandom();
    // The amount of oxygen a plant need to survive in night.
    private static final double PLANT_OXYGEN_REQUIRED = 0.00000002;
    // The amount of oxygen a plant generated during day time.
    private static final double OXYGEN_GENERATED = 0.0000005;


    // Individual characteristics (instance fields).

    // The seaweed's age.
    private int age;

    /**
     * Constructor for objects of class Seaweed
     */
    public Seaweed(boolean randomAge, Field field, Location location)
    {
        super(field, location);
        age = 0;
        if(randomAge) {
            age = rand.nextInt(MAX_AGE);
        }  
    }

   /**
     * This is what the seawead does most of the time - stay motionlessly under the water
     * @param newSeaweeds A list to return newly born shrimps.
     * @param atDayTime true if current step is daytime false otherwise.
     * @param oxygenLevel The inital level of dissolved oxygen in the water.
     * @param disease The disease may happened during simulation.  
     * @param step current step.
     * 
     * @return the oxygen level the species produced or consumed after action.
     */
    public double act(List<Creature> newSeaweeds, boolean atDayTime, double oxygenLevel, Disease disease,  int step)
    {
        incrementAge();
        if(oxygenLevel < PLANT_OXYGEN_REQUIRED){
            setDead();
            return 0;
        }    


        if(isAlive()){
            if(age >= MATURE_AGE)
                giveBirth(newSeaweeds);            
            }


        if(atDayTime)
            return OXYGEN_GENERATED;
        else
            return -PLANT_OXYGEN_REQUIRED;
        }

    /**
     * Increase the age.
     * This could result in the shrimp's death.
     */
    private void incrementAge()
    {
        age++;
        if(age > MAX_AGE) {
            setDead();
        }
    }

    /**
     * Check whether or not this shrimp is to give birth at this step.
     * New births will be made into free adjacent locations.
     * @param newSeaweeds A list to return newly propagated seaweed.
     */
    private void giveBirth(List<Creature> newSeaweeds)
    {
        createAdjacentCreatures(newSeaweeds, MAX_PROPAGATE_SIZE,
            (field, location) -> new Seaweed(false, field, location));
    }
}

